// Assistance is the main journey; the full intake remains available for review and manual entry.
function assistanceFocus(){const current=v.step>0&&v.step<7?Object.keys(intakeFields(v.step)):[];const conflicts=[...(v.sample&&!v.confirmedPrice&&!hasConversationUpdate('price')?['price']:[]),...(v.sample&&!v.confirmedDelivery&&!hasConversationUpdate('delivery')?['delivery']:[])];return [...new Set([...conflicts,...current.filter(key=>!v.data[key]?.trim()),...required(),...current])].slice(0,8)}
function assistanceCard(){const focus=assistanceFocus(),labels=BubsVendorContract.labelsForCategory(v.type),missing=required().length;return `<section class="assistance-card"><div><span class="eyebrow">LET’S FINISH THIS TOGETHER</span><h2>${missing?'Your information. A little help with the gaps.':'A second look, before your next chapter.'}</h2><p>${missing?`${missing} answers still need your input. Talk or type about your business, then review the suggested changes right here.`:'Ask for a correction or clarify a policy. Nothing changes until you apply the suggestion.'}</p>${focus[0]?`<p class="next-question"><b>We can start with:</b> ${safe(labels[focus[0]])}</p>`:''}</div><button class="primary" data-action="voice">Help me finish my profile →</button></section>`}
startScreen=function(){return header('Bring what you already have.<br><em>We’ll help finish the gaps.</em>','Your website, packages, and policies already tell much of your story. Start with a draft, add what’s missing through a conversation, and review your finished listing.')+`<div class="split"><section class="panel"><span class="eyebrow">START WITH YOUR BUSINESS</span><h2 style="margin-top:12px">What do you bring to the celebration?</h2><div class="category-line">${Object.keys(categories).map(c=>`<button data-category="${c}" class="${v.type===c?'active':''}">${c==='DJ'?'DJ & entertainment':c==='Caterer'?'Catering':c}</button>`).join('')}</div><label for="source-url">Your website or portfolio</label><input id="source-url" type="url" value="${safe(v.sourceUrl||'')}" placeholder="https://yourbusiness.com"><p class="helper">Document import is simulated in this demo. The sample uses five fictional source documents; conversation-based suggestions use the live API.</p><div class="start-actions"><button class="primary" data-action="import">Create my first draft →</button><button class="text" data-action="sample">Use ${safe(categories[v.type].name)} sample</button></div><hr class="divider"><h3>Prefer to talk it through?</h3><p style="margin:10px 0 18px">Tell the assistant about your business. You’ll see proposed updates, with your own words as evidence.</p><button class="secondary" data-action="voice">Help me finish my profile →</button><div class="manual-option"><button class="text" data-method="manual">Enter everything myself instead</button>${v.method==='manual'?`<p>Manual entry has the same 58-answer completion standard. Have your rate card, contract, service guide, portfolio permissions, and insurance records ready.</p><button class="secondary" data-depth="manual-start">Begin blank manual intake →</button>`:''}</div></section><aside class="note"><span class="eyebrow">FROM YOUR INFORMATION TO YOUR LISTING</span><h2 style="margin-top:16px">Less starting over.<br>More making it yours.</h2><ol><li><b>Start with a first draft</b><p>See supported details alongside their source documents.</p></li><li><b>Fill the gaps together</b><p>Use the assistant to add an answer or correct an outdated detail.</p></li><li><b>Review, apply, and publish</b><p>Check every section, then see the page couples will discover.</p></li></ol><p class="small">A finished demo listing is saved in your browser. You stay in control of every change.</p></aside></div>`}
const assistanceDetails=detailSection;detailSection=function(stage){return assistanceDetails(stage).replace('<div class="depth-layout">',assistanceCard()+'<div class="depth-layout">')};
overviewRequirements=function(){return `<details class="requirements-disclosure"><summary>What’s included in a complete profile? See the manual workload.</summary><div class="panel"><h3>The same requirements, whichever path you choose.</h3><p class="small">58 answers across six sections. Assistance drafts supported details; it does not skip the requirements.</p><div class="requirements-grid">${[1,2,3,4,5,6].map(stage=>`<button data-stage="${stage}"><b>${safe(vendorGroups[stage-1].title)}</b><span>${Object.keys(intakeFields(stage)).length} fields</span><small>${stageGather[stage]}</small></button>`).join('')}</div></div></details>`};
const assistedImport=importSample;importSample=async function(){v.method='website';await assistedImport()};
openVoice=async function(){if(v.method!=='website')v.method='voice';save();const focus=assistanceFocus(),focusStage=[1,2,3,4,5,6].find(stage=>focus[0] in intakeFields(stage));const modal=q('#assistant'),frame=q('#voice-frame');frame.onload=()=>frame.contentWindow.postMessage({type:'bubs-vendor-context',data:v.data,category:v.type,focus,section:focusStage?stages[focusStage]:(stages[v.step]||'Your profile')},location.origin);frame.src='voice-setup.html?v=12#voice';modal.showModal()};
const assistedPreview=preview;preview=function(){return assistanceCard()+assistedPreview()};
render();
